package com.bank.acctnum;

import java.util.*;
import java.util.logging.*;

public class AccountNumberDemo {
    private static final Logger log = Logger.getLogger("AccountNumber");
    static {
        ConsoleHandler h = new ConsoleHandler();
        h.setFormatter(new SimpleFormatter());
        log.setUseParentHandlers(false);
        log.addHandler(h);
    }

    public static void main(String[] args) {
        AccountNumberService service = new AccountNumberService();

        List<String> accounts = service.mintAccountNumbers(5);
        log.info(() -> "Minted accounts: " + accounts);

        List<String> ranked = service.rankedNames(List.of("Vikram", "Rohit", "Sneha"));
        ranked.forEach(r -> log.info(() -> "  " + r));
    }
}

// ─── Would be in service/AccountNumberService.java ───
class AccountNumberService {
    // rangeClosed(1, count): 1..count INCLUSIVE, mapToObj formats each
    List<String> mintAccountNumbers(int count) {
        return java.util.stream.IntStream.rangeClosed(1, count)
            .mapToObj(i -> String.format("ACC-%04d", i))   // int → "ACC-0001"
            .collect(java.util.stream.Collectors.toList());
    }

    // range(0, size): 0..size-1 EXCLUSIVE end — index-based iteration for ranks
    List<String> rankedNames(List<String> names) {
        return java.util.stream.IntStream.range(0, names.size())
            .mapToObj(i -> (i + 1) + ". " + names.get(i))  // pair index with element
            .collect(java.util.stream.Collectors.toList());
    }
}
